def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
M = '"Mermail"'
A = '"Atlantean"'
SENT = 'Cuando esta carta sea mandada al Cementerio para activar el efecto de un monstruo de AGUA: '
FSA = 'monstruo de Tipo Pez, Serpiente Marina o Aqua'
ES = {
"Mermail Abyssnose": 'Cuando esta carta destruya en batalla un monstruo del adversario y lo mande al Cementerio: puedes descartar 1 monstruo de AGUA al Cementerio; Invoca de Modo Especial 1 monstruo ' + M + ' de tu Deck en Posición de Defensa boca arriba.' + once("Mermail Abyssnose"),
"Atlantean Marksman": 'Cuando esta carta inflija daño de batalla a tu adversario: puedes Invocar de Modo Especial 1 monstruo ' + A + ' de Tipo Serpiente Marina de Nivel 4 o menor de tu Deck, excepto "Atlantean Marksman". ' + SENT + 'selecciona 1 carta Colocada que controle tu adversario; destruye ese objetivo.',
"Atlantean Attack Squad": 'Esta carta gana 800 ATK mientras controles un monstruo de Tipo Pez, Serpiente Marina o Aqua boca arriba distinto de esta carta.',
"Abysstrite, the Atlantean Spirit": '2 o más monstruos de AGUA de Nivel 7\nLos monstruos de AGUA que controlas ganan 300 ATK/DEF por cada material acoplado a esta carta. Sólo puedes usar cada uno de los siguientes efectos de "Abysstrite, the Atlantean Spirit" una vez por turno. Si esta carta es Invocada por Xyz: puedes seleccionar 1 ' + FSA + ' de Nivel 7 o menor en tu Cementerio; Invócalo de Modo Especial. Puedes desacoplar 1 material de esta carta; Coloca 1 Trampa "Abyss-" de tu Deck.',
"Abyssrhine, the Atlantean Spirit": '(Esta carta se trata siempre como una carta ' + M + '.)\nPuedes Sacrificar esta carta de tu mano y 1 monstruo ' + A + ' o ' + M + ' de tu mano o Campo; toma de tu Deck 1 ' + FSA + ' de Nivel 7 y añádelo a tu mano o Invócalo de Modo Especial; además, durante el resto de este turno no puedes Invocar de Modo Especial desde el Extra Deck, excepto monstruos de AGUA. Durante el turno de tu adversario (Efecto Rápido): puedes desterrar esta carta de tu Cementerio y descartar 1 carta al Cementerio; roba 1 carta.' + each("Abyssrhine, the Atlantean Spirit"),
"Neptabyss, the Atlantean Prince": 'Puedes mandar al Cementerio 1 monstruo ' + A + ' de tu Deck, excepto "Neptabyss, the Atlantean Prince"; añade a tu mano 1 carta ' + A + ' de tu Deck, excepto "Neptabyss, the Atlantean Prince". Si esta carta es mandada al Cementerio para activar el efecto de un monstruo de AGUA: selecciona 1 monstruo ' + A + ' en tu Cementerio, excepto "Neptabyss, the Atlantean Prince"; Invócalo de Modo Especial.' + each("Neptabyss, the Atlantean Prince"),
"Mermail Abyssmander": 'Puedes desterrar esta carta de tu Cementerio para activar 1 de estos efectos;\n● Aumenta en 1 los Niveles de todos los monstruos ' + M + ' que controles en ese momento.\n● Aumenta en 2 los Niveles de todos los monstruos ' + M + ' que controles en ese momento.',
"Mermail Abyssmegalo": 'Puedes descartar al Cementerio otros 2 monstruos de AGUA; Invoca esta carta de Modo Especial desde tu mano. Cuando sea Invocada de esta forma: puedes añadir a tu mano 1 Mágica/Trampa "Abyss-" de tu Deck. Puedes Sacrificar otro monstruo de AGUA en Posición de Ataque; esta carta puede realizar un segundo ataque durante cada Battle Phase de este turno.',
"Mermail Abyssturge": 'Cuando esta carta sea Invocada de Modo Normal o Especial: puedes descartar 1 monstruo de AGUA al Cementerio y, después, seleccionar 1 monstruo de AGUA de Nivel 3 o menor en tu Cementerio; añade ese objetivo a tu mano.' + once("Mermail Abyssturge"),
"Mermail Abyssteus": 'Puedes descartar al Cementerio otro monstruo de AGUA; Invoca esta carta de Modo Especial desde tu mano. Cuando sea Invocada de esta forma: puedes añadir a tu mano 1 monstruo ' + M + ' de Nivel 4 o menor de tu Deck.' + once("Mermail Abyssteus"),
"Mermail Abysslinde": 'Si esta carta en el Campo es destruida y mandada al Cementerio: puedes Invocar de Modo Especial 1 monstruo ' + M + ' de tu Deck, excepto "Mermail Abysslinde".' + once("Mermail Abysslinde"),
"Mermail Abyssocea": 'Puedes seleccionar 1 monstruo ' + M + ' que controles; Invoca de Modo Especial desde tu Deck cualquier número de monstruos ' + M + ' de Nivel 4 o menor cuyos Niveles combinados sean menores o iguales que el Nivel de ese monstruo y, después, manda ese monstruo al Cementerio.' + once("Mermail Abyssocea"),
"Legendary Atlantean Tridon": 'Puedes Sacrificar esta carta y 1 monstruo de Tipo Serpiente Marina; Invoca de Modo Especial 1 "Poseidra, the Atlantean Dragon" de tu mano o Deck y, después, todos los monstruos que controla tu adversario en ese momento pierden 300 ATK.',
"Atlantean Heavy Infantry": 'Durante tu Main Phase, puedes Invocar de Modo Normal 1 monstruo de Tipo Serpiente Marina de Nivel 4 o menor además de tu Invocación Normal o Colocación. (Sólo puedes ganar este efecto una vez por turno.) ' + SENT + 'selecciona 1 carta boca arriba que controle tu adversario; destruye ese objetivo.',
"Mermail Abyssleed": 'Puedes descartar al Cementerio otros 3 monstruos de AGUA; Invoca esta carta de Modo Especial desde tu mano. Cuando sea Invocada de esta forma: puedes seleccionar 1 Mágica/Trampa "Abyss-" en tu Cementerio; añade ese objetivo a tu mano. Puedes Sacrificar otro monstruo ' + M + ' en Posición de Ataque; manda al Cementerio 1 carta al azar de la mano de tu adversario.' + once("Mermail Abyssleed"),
"Poseidra, the Atlantean Dragon": 'Puedes Sacrificar 3 monstruos de AGUA de Nivel 3 o menor; Invoca esta carta de Modo Especial desde tu mano o Cementerio. Cuando lo hagas: devuelve a la mano todas las Cartas Mágicas y de Trampa en el Campo y, si lo haces, si 3 o más cartas son devueltas a la mano por este efecto, todos los monstruos que controla tu adversario en ese momento pierden 300 ATK por cada una.',
"Mermail Shadow Squad": '(Esta carta se trata siempre como una carta ' + A + '.)\nPuedes descartar 1 carta al Cementerio; los monstruos de AGUA que controlas en ese momento pasan a ser de Nivel 7 hasta el final de este turno. Si esta carta es mandada al Cementerio para activar el efecto de un monstruo de AGUA: Invoca de Modo Especial 1 monstruo ' + A + ' o ' + M + ' de Nivel 4 o menor de tu Deck, excepto "Mermail Shadow Squad"; además, durante el resto de este turno no puedes Invocar de Modo Especial desde el Extra Deck, excepto monstruos de AGUA.' + each("Mermail Shadow Squad"),
"Mermail Abysspike": 'Cuando esta carta sea Invocada de Modo Normal o Especial: puedes descartar 1 monstruo de AGUA al Cementerio; añade a tu mano 1 monstruo de AGUA de Nivel 3 de tu Deck.' + once("Mermail Abysspike"),
"Mermail Abysstrite": '3 monstruos de Nivel 3\nDurante el turno de cualquier jugador, cuando tu adversario seleccione exactamente 1 monstruo ' + M + ' boca arriba que controles para un ataque, o con un efecto de Mágica/Trampa que podría haber seleccionado esta carta (excepto durante el Damage Step): puedes desacoplar 1 Material Xyz de esta carta; ese ataque/efecto pasa a seleccionar esta carta. Cuando esta carta sea destruida y mandada al Cementerio: puedes seleccionar 1 monstruo ' + M + ' en tu Cementerio, excepto "Mermail Abysstrite"; Invoca de Modo Especial ese objetivo.',
"Poseidra Abyss, the Atlantean Dragon Lord": '3 monstruos de Nivel 7\nUna vez por turno, también puedes Invocar por Xyz "Poseidra Abyss, the Atlantean Dragon Lord" usando 1 Monstruo Xyz ' + A + ' o ' + M + ' que controles. (Transfiere sus materiales a esta carta.) Una vez por turno: puedes desacoplar 2 materiales de esta carta y, después, mandar al Cementerio 1 monstruo de AGUA de tu mano o Deck; devuelve a la mano hasta 3 cartas que controle tu adversario. Si esta carta Invocada por Xyz es mandada al Cementerio: puedes descartar 1 carta al Cementerio; Invoca de Modo Especial desde tu mano y/o Cementerio 3 monstruos de Tipo Pez, Serpiente Marina y/o Aqua de Nivel 3 o menor.',
"Mermail Abyssgunde": 'Si esta carta es descartada al Cementerio: puedes seleccionar 1 monstruo ' + M + ' en tu Cementerio, excepto "Mermail Abyssgunde"; Invoca de Modo Especial ese objetivo.' + once("Mermail Abyssgunde"),
"Mermail Abyssnerei": '(Efecto Rápido): puedes descartar esta carta y, después, seleccionar 1 monstruo de AGUA que controles; destruye otro monstruo de AGUA de tu mano o Campo y, si lo haces, el monstruo seleccionado gana ATK/DEF iguales al ATK/DEF original del monstruo destruido, hasta el final de este turno. Si esta carta es mandada del Campo al Cementerio: puedes robar 1 carta y, después, descartar 1 carta.' + each("Mermail Abyssnerei"),
"Call of the Atlanteans": 'Selecciona 3 monstruos de Tipo Serpiente Marina de Nivel 3 o menor en tu Cementerio; Invoca de Modo Especial los 3. No puedes Invocar de Modo Especial ningún otro monstruo durante el turno en que actives esta carta.',
"Mermail Abyssdine": 'Cuando esta carta sea añadida a tu mano desde tu Deck o Cementerio por un efecto de carta: puedes Invocar esta carta de Modo Especial desde tu mano. Debes controlar un monstruo ' + M + ' para activar y resolver este efecto. Cuando esta carta sea Invocada de Modo Especial por el efecto de un monstruo ' + M + ': puedes seleccionar 1 monstruo ' + M + ' de Nivel 3 o menor en tu Cementerio; Invoca de Modo Especial ese objetivo. Sólo puedes usar 1 efecto de "Mermail Abyssdine" por turno, y sólo una vez ese turno.',
"Atlantean Dragoons": 'Todos tus monstruos de Tipo Serpiente Marina de Nivel 3 o menor pueden atacar directamente. Si esta carta es mandada al Cementerio para activar el efecto de un monstruo de AGUA: añade a tu mano 1 monstruo de Tipo Serpiente Marina de tu Deck, excepto "Atlantean Dragoons".',
"Mermail Abyssgaios": '2 monstruos de AGUA de Nivel 7\nMientras esta carta boca arriba tenga Material Xyz, los monstruos de Nivel 5 o mayor no pueden atacar. Una vez por turno, durante el turno de cualquier jugador: puedes desacoplar 1 Material Xyz de esta carta; niega, hasta el final del turno, los efectos de todos los monstruos boca arriba que controla tu adversario en ese momento que tengan menos ATK que esta carta.',
"Mermail Abyssbalaen": 'Puedes descartar al Cementerio otros 4 monstruos ' + M + '; Invoca esta carta de Modo Especial desde tu mano. Cuando lo hagas: selecciona cartas que controle tu adversario, hasta el número de monstruos ' + M + ' en tu Cementerio (si es posible); esta carta gana 500 ATK y, si lo hace, destruye esos objetivos (si los hay). Puedes Sacrificar otro monstruo ' + M + ' boca arriba en Posición de Ataque; esta carta gana el siguiente efecto este turno.\n● Al inicio del Damage Step, si esta carta combate con un monstruo en Posición de Defensa: destruye ese monstruo.',
"Mermail Abysslung": 'Tu adversario no puede seleccionar monstruos de AGUA boca arriba para sus ataques, excepto éste. Todos los monstruos de AGUA que controlas ganan 300 ATK.',
"Mermail Abysshilde": 'Si esta carta es mandada al Cementerio: puedes Invocar de Modo Especial 1 monstruo ' + M + ' de tu mano, excepto "Mermail Abysshilde".' + once("Mermail Abysshilde"),
"Poseidra, the Storming Atlantean": 'Mientras controles un monstruo, excepto "Poseidra, the Storming Atlantean", los monstruos de tu adversario no pueden seleccionar esta carta para sus ataques. Sólo puedes usar cada uno de los siguientes efectos de "Poseidra, the Storming Atlantean" una vez por turno. Puedes mandar al Cementerio otro monstruo de AGUA de tu mano o boca arriba de tu Campo; Invoca esta carta de Modo Especial desde tu mano. Si esta carta es Invocada de Modo Normal o Especial: puedes mandar al Cementerio 1 monstruo ' + A + ' o ' + M + ' de tu Deck y, después, seleccionar 1 carta que controle tu adversario; devuélvela a la mano.',
}
